import {fmt,esc,versionDirty,evaluateStudy} from './core.mjs';
import {generationBanner} from './generations.mjs';
import {evaluationPage} from './evaluations.mjs';
import {lyricsState,LYRICS_STATUS} from './generation-core.mjs';
const paths={wave:'M3 10v4m4-8v12m5-15v18m5-15v12m4-8v4',music:'M9 18V5l12-2v13M9 8l12-2M9 18a3 3 0 1 1-3-3c1.7 0 3 1.3 3 3Zm12-2a3 3 0 1 1-3-3c1.7 0 3 1.3 3 3Z',spark:'m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4L12 3Z',plus:'M12 5v14M5 12h14',upload:'M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5',download:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',arrow:'M12 19V5m-6 6 6-6 6 6',play:'m8 5 11 7-11 7Z',pause:'M8 5v14M16 5v14',back:'M5 5v14m14-14-10 7 10 7Z',volume:'m11 5-6 4H2v6h3l6 4V5Zm5 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',edit:'m15 5 4 4M4 20l5-1L21 7l-4-4L5 15l-1 5Z',layers:'m12 3 10 5-10 5L2 8l10-5Zm-10 9 10 5 10-5M2 16l10 5 10-5',chart:'M4 3v18h17M8 16v-5m5 5V7m5 9V4',info:'M12 11v6m0-10v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',close:'m6 6 12 12M6 18 18 6',sliders:'M4 7h16M4 17h16M8 4v6m8 4v6',file:'M14 2H5v20h14V7l-5-5Zm0 0v5h5M8 12h8m-8 4h6',headphones:'M3 14v-3a9 9 0 0 1 18 0v3M3 12h4v9H3v-9Zm14 0h4v9h-4v-9Z',chevron:'m9 5 7 7-7 7',piano:'M3 4h18v16H3V4Zm6 0v16m6-16v16M7 4v8h4V4m2 0v8h4V4'};
export function createUI(state,player,getVersion){
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.music}"/></svg>`;
function shell(){return `${rail()}<div class="shell">${topbar()}${state.page==='studio'?studio():state.page==='research'?research():state.page==='evaluation'?evaluationPage(state):capabilities()}${transport()}</div>`;}
function rail(){return `<aside class="rail" aria-label="主导航"><div class="brand-mark" title="声间 Sonara">${icon('wave')}</div><button class="nav-btn ${state.page==='studio'?'active':''}" data-act="page" data-page="studio" aria-label="创作室" title="创作室">${icon('music')}</button><button class="nav-btn ${state.page==='research'?'active':''}" data-act="page" data-page="research" aria-label="验证记录" title="验证记录">${icon('chart')}</button><button class="nav-btn ${state.page==='evaluation'?'active':''}" data-act="page" data-page="evaluation" aria-label="作品评测" title="作品评测">${icon('headphones')}</button><div class="rail-spacer"></div><button class="nav-btn ${state.page==='capabilities'?'active':''}" data-act="page" data-page="capabilities" aria-label="能力与使用说明" title="能力与使用说明">${icon('info')}</button><div class="avatar" title="本机工作区">S</div></aside>`;}
function topbar(){return `<header class="topbar"><div class="flex"><button class="wordmark" data-act="page" data-page="studio" aria-label="回到创作室">声间<span>SONARA</span></button><div class="breadcrumb"><span>/</span><button class="project-picker" data-act="projects">我的创作 ${icon('chevron')}</button></div></div><div class="flex top-actions"><button class="icon-btn" data-act="page" data-page="evaluation" aria-label="作品评测" title="作品评测">${icon('headphones')}</button><a class="btn quiet compact" href="/compose.html">从想法创作</a><span id="save-state" class="save-state">${esc(state.saveText)}</span><button class="icon-btn" data-act="projects" aria-label="我的创作" title="我的创作">${icon('layers')}</button><button class="icon-btn" data-act="page" data-page="research" aria-label="验证记录" title="验证记录">${icon('chart')}</button><button class="icon-btn" data-act="page" data-page="capabilities" aria-label="能力说明" title="能力说明">${icon('info')}</button><button class="btn quiet compact" data-act="new-project">${icon('plus')}新建作品</button></div></header>`;}
function studio(){const p=state.project,v=p.working;return `<div class="project-header"><div><span class="eyebrow">A LITTLE CLOSER TO YOUR SOUND</span><div class="project-title"><h1>${esc(p.title)}</h1><button class="icon-btn" data-act="edit-project" aria-label="编辑作品信息">${icon('edit')}</button></div><div class="project-meta"><span>${p.language==='en'?'英文创作':'中文创作'}</span><span class="divider">/</span><span>${v?v.source==='demo'?`${v.direction==='warm'?'温暖独立流行':'明亮轻快流行'} · ${v.bpm} BPM`:v.source==='generated'?'服务生成 · 待试听评测':'导入音频 · 自由创作':'从一个想法开始'}</span><span class="badge ${v?.source==='demo'?'amber':''}">${v?v.source==='demo'?'原创器乐演示':v.source==='generated'?(v.mode==='instrumental'?'生成的纯音乐':'生成的演唱'):'你的音频':'未加入音频'}</span></div></div><div class="flex project-buttons"><button class="btn" data-act="generation-open">${icon('spark')}生成演唱</button><button class="btn" data-act="import">${icon('upload')}导入小样</button><button class="btn primary" data-act="export" ${!v?'disabled':''}>${icon('download')}导出作品</button></div></div><nav class="progress-steps" aria-label="创作进度">${['表达想法','确定方向','形成歌曲','一起打磨','完成作品'].map((s,i)=>`${i?'<i class="step-line"></i>':''}<button class="step ${p.stage===i+1?'active':''}" data-act="step" data-step="${i+1}" aria-current="${p.stage===i+1?'step':'false'}"><span class="num">${p.stage>i+1?'✓':i+1}</span>${s}</button>`).join('')}</nav>${generationBanner(state)}<a class="sample-entry" href="/youth-song.html"><span><b>原创样本 · 那条放学后的路</b><small>以 90 后的青春为主题，听听从词曲、编配到演唱的完整作品小样。</small></span><span>试听整首 ↗</span></a><main id="workspace" class="workspace">${conversation()}${songCanvas()}${versions()}</main>`;}
function conversation(){const p=state.project;return `<section class="panel conversation-panel" aria-label="创作对话"><div class="panel-heading"><div class="flex">${icon('spark')}<h2>创作伙伴</h2></div><span class="badge">规则演示</span></div><div class="assistant-intro"><div class="flex"><div class="assistant-symbol">${icon('wave')}</div><h3>一起，找到这首歌的样子</h3></div><p>${esc(p.brief||'从一个想法出发，边听边打磨。')}</p></div><div class="conversation" id="conversation" aria-live="polite">${p.messages.slice(-12).map(m=>`<div class="message ${m.role}">${m.role==='assistant'?'<span class="message-label">声间 · 创作伙伴</span>':''}${esc(m.text)}</div>`).join('')}</div>${proposalView()}<div class="suggestion-list">${['副歌更有力量','伴奏轻一点','鼓声小一点'].map(t=>`<button class="suggestion" data-act="suggest" data-text="${t}">${t}</button>`).join('')}<button class="suggestion" data-act="generation-open">准备歌词演唱</button><button class="suggestion" data-act="directions">试听器乐演示</button></div><form id="chat-form" class="composer"><textarea id="chat-input" maxlength="2000" placeholder="说说你想怎么改这首歌…" aria-label="给创作伙伴的想法"></textarea><div class="composer-footer"><span>先确认方案，再听变化</span><button class="send-btn" aria-label="发送想法" type="submit">${icon('arrow')}</button></div></form></section>`;}
function proposalView(){const p=state.proposal;if(!p)return '';return `<div class="proposal"><h3>${icon('sliders')} ${esc(p.title)}</h3><p>${esc(p.explanation)}</p>${p.kind==='mix'?'<button class="btn primary compact" data-act="apply-proposal">确认修改 · 保留原版</button>':p.kind==='external'?'<button class="btn compact" data-act="request">导出制作需求单</button>':p.kind==='brief'?'<button class="btn compact" data-act="directions">试听器乐方向</button>':''}<button class="btn quiet compact" data-act="dismiss-proposal">先不修改</button></div>`;}
function songCanvas(){const v=state.project.working,pv=getVersion()||v;return `<section class="panel song-panel" aria-label="歌曲画布"><div class="canvas-top flex between"><div class="flex"><h2>歌曲画布</h2>${v&&versionDirty(state.project)?'<span class="badge amber">有未归档调整</span>':''}</div><span class="small muted">${v?`${fmt(v.trim.end-v.trim.start)} · ${v.tracks.length} 条音轨`:'等待第一段音乐'}</span></div><div class="canvas-tabs" role="tablist" aria-label="歌曲编辑方式"><button class="tab ${state.tab==='lyrics'?'active':''}" role="tab" aria-selected="${state.tab==='lyrics'}" data-act="tab" data-tab="lyrics">歌词与段落</button><button class="tab ${state.tab==='stems'?'active':''}" role="tab" aria-selected="${state.tab==='stems'}" data-act="tab" data-tab="stems">音轨调整</button></div>${v?`<p id="peak-warning" class="peak-warning" role="status"></p><div class="song-overview"><div class="flex between" style="margin-bottom:14px"><span class="small muted">${state.ab==='A'?'A 基准试听 · 下方编辑为 B':'当前作品 · B'}${v.source==='demo'?' / 无演唱器乐':''}</span><button class="icon-btn" data-act="trim" aria-label="裁剪导出范围" title="裁剪导出范围">${icon('sliders')}</button></div><div class="waveframe" id="waveform" role="slider" tabindex="0" aria-label="波形播放位置" aria-valuemin="0" aria-valuemax="${pv.duration.toFixed(1)}" aria-valuenow="0">${waveHTML()}<span class="playhead" id="playhead"></span></div><div class="time-ruler">${Array.from({length:5},(_,i)=>`<span>${fmt(pv.duration*i/4)}</span>`).join('')}</div></div><div class="sections">${v.sections.map(s=>`<button class="section-pill ${state.section===s.id?'selected':''}" data-kind="${s.id}" data-act="section" data-section="${s.id}" title="${esc(s.name)} ${fmt(s.start)}–${fmt(s.end)}">${esc(s.name)}</button>`).join('')}</div>${state.tab==='lyrics'?lyricsView():stemsView()}`:`<div class="empty" style="padding:45px 25px">${icon('headphones')}<h2 style="margin:20px 0 12px">让想法有一个声音</h2><p>记录故事和歌词，试听器乐方向。<br>也可以导入已有小样，在这里继续打磨。</p><div class="flex" style="justify-content:center;margin-top:24px;flex-wrap:wrap"><button class="btn primary" data-act="generation-open">让歌词唱出来</button><button class="btn quiet" data-act="directions">试听器乐演示</button><button class="btn" data-act="import">导入我的小样</button></div></div><div class="notice canvas-notice">生成演唱需要连接音乐服务；连接状态显示在上方。器乐演示不会根据歌词生成。也可以只导入音频直接加工。</div><div class="lyrics-content"><label class="stack">歌词草稿<textarea data-seed-lyrics rows="6" maxlength="12000" aria-label="已有歌词草稿" placeholder="写下已经想到的歌词…">${esc(state.project.seedLyrics||'')}</textarea></label></div>`}</section>`;}
function waveHTML(){return Array.from({length:120},(_,i)=>`<span class="wavebar" style="height:${state.peaks.length?Math.max(3,state.peaks[i]*72):3}px;${state.peaks.length?'':'opacity:.25'}"></span>`).join('');}
function lyricsView(){const p=state.project,v=p.working;return `<div class="notice canvas-notice">${esc(LYRICS_STATUS[lyricsState(v)])}${v.lyricsSnapshot?'<button class="btn quiet compact" data-act="generation-lyrics-snapshot">查看生成时的歌词</button>':''}</div><div class="lyrics-toolbar"><div class="flex"><h3>歌词草稿</h3><span class="badge">${p.language==='en'?'EN':'中文'}</span></div><div class="flex"><button class="icon-btn" data-act="section-time" aria-label="编辑选中段落的时间" title="编辑段落时间">${icon('clock')}</button><button class="btn quiet compact" data-act="edit-lyrics">${icon(state.editingLyrics?'check':'edit')}${state.editingLyrics?'完成编辑':'编辑歌词'}</button></div></div><div class="lyrics-content">${v.sections.filter(s=>!['intro','outro'].includes(s.id)).map(s=>`<div class="lyric-block ${s.id===state.section?'selected':''}"><div class="lyric-label"><button data-act="section" data-section="${s.id}" style="font:inherit;color:inherit;padding:0;min-height:24px">${esc(s.name)}</button><br>${fmt(s.start)}</div>${state.editingLyrics?`<textarea class="lyric-edit" data-lyric="${s.id}" aria-label="${esc(s.name)}歌词" maxlength="5000" placeholder="写下${esc(s.name)}的歌词…">${esc(s.lyrics)}</textarea>`:`<div class="lyric-lines">${s.lyrics?esc(s.lyrics):'<span class="lyric-empty">还没有歌词，留一点空间给灵感。</span>'}</div>`}</div>`).join('')}</div>`;}
function stemsView(){const v=state.project.working;return `<div class="stems-content"><div class="flex between"><h3>听见每一个部分</h3><button class="btn quiet compact" data-act="add-stem">${icon('plus')}添加音轨</button></div><p class="small muted" style="line-height:1.8;margin:12px 0">S 单独试听 · M 静音。音量调整作用于整首歌曲；对话方案可只调整选中段落。</p>${v.tracks.map(t=>`<div class="stem-row" style="--stem:${t.color}"><div class="flex"><div class="stem-title"><i class="stem-dot"></i>${esc(t.name)}</div><span class="badge">${t.assetId?'导入音轨':'原创器乐'}</span></div><div class="stem-controls"><input type="range" min="0" max="180" value="${Math.round(t.gain*100)}" data-gain="${t.id}" aria-label="${esc(t.name)}音量"><span class="stem-value" id="gain-${t.id}">${Math.round(t.gain*100)}%</span><button class="${t.solo?'enabled':''}" data-act="solo" data-track="${t.id}" aria-pressed="${t.solo}" aria-label="单独试听${esc(t.name)}">S</button><button class="${t.muted?'enabled':''}" data-act="mute" data-track="${t.id}" aria-pressed="${t.muted}" aria-label="静音${esc(t.name)}">M</button></div></div>`).join('')}<div class="notice" style="margin-top:20px">${v.tracks.some(t=>t.kind==='mix')?'当前包含混合音轨。自动分轨尚未接入；可导入外部分轨结果，获得独立控制。':'这些是可独立编辑的音轨。修改歌词或演唱需要额外制作，调节音量不会改变音符和发音。'}</div>${v.effects.length?`<div class="flex between" style="margin-top:17px"><span class="small muted">已应用 ${v.effects.length} 项局部调整</span><button class="btn quiet compact" data-act="clear-effects">移除局部调整</button></div>`:''}</div>`;}
function versions(){const p=state.project;return `<aside class="panel versions-panel" aria-label="版本记录"><div class="panel-heading"><div class="flex">${icon('layers')}<h2>版本记录</h2></div><span class="small muted">${String(p.versions.length).padStart(2,'0')}</span></div><div class="version-list">${p.versions.slice().reverse().map((v,i)=>`<div class="version-card ${p.working?.id===v.id?'current':''}"><div class="flex between"><h3>${esc(v.name)}</h3><span class="badge ${p.working?.id===v.id?'lime':''}">V${p.versions.length-i}</span></div><p>${esc(v.notes)}</p><div class="flex between" style="margin-top:10px"><span class="v-time">${new Date(v.createdAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</span>${v.id===p.compareId?'<span class="small muted">A 基准</span>':''}</div><div class="version-card-actions"><button data-act="load-version" data-version="${v.id}">${p.working?.id===v.id?'恢复此版':'继续此版'}</button><button data-act="compare-version" data-version="${v.id}">设为 A</button></div></div>`).join('')||'<div class="empty">第一段音乐加入后，<br>在这里留下每次创作。</div>'}</div><div class="version-footer"><button class="btn quiet" data-act="save-version" ${!p.working?'disabled':''}>${icon('plus')}保存当前版本</button></div><p class="version-tip">保存版本会保留当时的音轨、歌词和段落。切换版本时，未归档的调整也会自动留存。</p><div class="insight"><div class="insight-title">${icon('headphones')}留一点时间给耳朵</div>选择一个基准版本，用底部 A / B 切换试听。喜欢的部分，值得留下。</div></aside>`;}
function transport(){const p=state.project,v=getVersion();return `<footer class="transport" aria-label="播放器"><div class="track-art">${icon('wave')}</div><div class="transport-info"><h3>${esc(p.title)}</h3><p id="playing-label">${state.ab==='A'?'A · 基准版本':'B · 当前修改'}${v?.source==='demo'?' · 器乐':''}</p></div><div class="transport-controls"><button class="icon-btn" data-act="restart" aria-label="回到开头" ${!v?'disabled':''}>${icon('back')}</button><button class="play-btn" id="play-btn" data-act="play" aria-label="播放" ${!v?'disabled':''}>${icon('play')}</button></div><div class="transport-seek"><span class="time" id="current-time">00:00</span><input type="range" id="seek" aria-label="播放进度" min="0" max="${v?.duration||1}" step="0.1" value="0" ${!v?'disabled':''}><span class="time" id="total-time">${fmt(v?.duration||0)}</span></div><span class="ab-label">试听比较</span><div class="ab-control" role="group" aria-label="版本比较"><button data-act="ab" data-ab="A" aria-pressed="${state.ab==='A'}" class="${state.ab==='A'?'selected':''}" ${!v?'disabled':''}>A</button><button data-act="ab" data-ab="B" aria-pressed="${state.ab==='B'}" class="${state.ab==='B'?'selected':''}" ${!v?'disabled':''}>B</button></div><div class="transport-volume">${icon('volume')}<input id="volume" type="range" min="0" max="100" value="${player.volume*100}" aria-label="监听音量"></div></footer>`;}
function research(){const m=evaluateStudy(state.records);return `<main class="page" id="workspace"><div class="page-header"><div><span class="eyebrow">LISTEN. LEARN. MAKE IT BETTER.</span><h1 style="margin-top:10px">让真实创作，回答产品问题</h1><p>六位音乐爱好者，各自带来一个想法。记录他们能否完成作品、改得满意，以及愿不愿意再次回来。以下初始记录为空，填写实际观察结果。</p></div><button class="btn" data-act="export-study">${icon('download')}导出验证记录</button></div><div class="notice">记录仅保存在此浏览器。使用参与者编号，不记录姓名和联系方式；开始前征得参与者对记录与音频使用的同意。人工辅助和规则演示均需说明。</div><div class="metrics">${[['愿意分享完整歌曲',m.shared,'4 人','已完成且愿意分享'],['修改有效且保留原意',m.controlled,'4 人','至少两处修改，效果与保留项均达标'],['一周内自愿回访',m.returned,'3 人','实际回访日期在首次测试后 1–7 天'],['中英文成功案例',m.languages.filter(l=>l.passed).length,'2 组','各有完成、分享和可控修改案例']].map(([label,value,target,hint])=>`<div class="panel metric"><h3>${label}</h3><strong>${value}<span class="small muted"> / ${target}</span></strong><p>${hint}</p></div>`).join('')}</div><div class="flex between" style="margin:27px 0 15px"><h2>首轮参与者</h2><span class="badge ${m.passed?'lime':''}">${m.passed?'达到首轮验证门槛':`已完成 ${m.attended} / 6 场测试`}</span></div><section class="panel table-scroll"><table class="record-table"><thead><tr><th>参与者</th><th>创作语言</th><th>首次测试</th><th>修改次数</th><th>作品反馈</th><th>记录</th></tr></thead><tbody>${state.records.map(r=>`<tr><td>${r.id}</td><td>${r.language==='zh'?'中文':'英文'}</td><td>${r.sessionDate||'尚未测试'}</td><td>${r.completed?r.modifications:'—'}</td><td>${r.completed?r.shareReady?'愿意分享':'仍需打磨':'等待真实创作'}</td><td><button class="btn compact quiet" data-act="study-record" data-record="${r.id}">${r.completed?'更新记录':'填写记录'}</button></td></tr>`).join('')}</tbody></table></section><h2 class="section-title">每位参与者完成同一条创作路径</h2><section class="panel plan-list"><ol><li>带着自己的想法或歌词，选择一个满意的音乐方向。</li><li>通过人工辅助或外部工具形成完整歌曲，并导入工作台。</li><li>提出并完成至少两处具体修改，比较前后版本。</li><li>判断是否愿意分享，并在一周内观察是否自愿回来创作。</li></ol></section><h2 class="section-title">这轮要回答的问题</h2><div class="capabilities-grid"><section class="panel cap-card"><h3>作品是不是更像用户自己？</h3><p>记录最想保留的内容、最不满意的部分，以及每次修改是否保留了重要内容。单独记录中英文发音、断句与表达问题。</p></section><section class="panel cap-card"><h3>体验能否持续成立？</h3><p>记录完成时间、尝试次数、外部处理费用与人工帮助次数。器乐示例不能验证演唱质量；没有进行的项目保留为“未评估”。</p></section></div></main>`;}
function capabilities(){return `<main class="page" id="workspace"><div class="page-header"><div><span class="eyebrow">AN HONEST CREATIVE WORKSPACE</span><h1 style="margin-top:10px">从能听见的变化开始</h1><p>声间是一套创作体验验证工作台。可以实际试听与处理音频，也保留尚需外部制作的环节，让每一次验证有据可依。</p></div><button class="btn primary" data-act="page" data-page="studio">回到创作室</button></div><div class="capabilities-grid"><section class="panel cap-card"><div class="flex">${icon('sliders')}<h2>现在可以直接完成</h2></div><ul><li>两个原创器乐方向，具有完整歌曲段落。</li><li>导入音频或独立音轨，调节音量、静音、独听。</li><li>对选中段落调整音轨电平，并保存新版本。</li><li>编辑中英文歌词草稿、段落时间与裁剪范围。</li><li>切换 A/B 试听，导出立体声 WAV 和歌词。</li><li>保存本机项目、记录验证结果并导出 CSV。</li><li>逐项评测真实歌曲或纯音乐，保存版本快照与费用记录。</li></ul><span class="badge lime">实际音频处理 · 本机完成</span></section><section class="panel cap-card"><div class="flex">${icon('spark')}<h2>需要外部制作支持</h2></div><ul><li>真实演唱和纯音乐已有候选服务接入口，连接账户后才可生成；音质尚未实测。</li><li>自动分离混合音频中的人声与乐器。</li><li>改词保留旋律、改演唱或生成新配器。</li><li>精确修正发音、音准或执行专业混音母带。</li></ul><p>导出制作需求单，交给外部工具或人工制作，再把结果作为新版本导入。对话建议采用明确标注的规则演示，未连接语言模型。</p><span class="badge amber">服务连接与音质评测分别显示</span></section><section class="panel cap-card"><h2>音频与版本如何保存</h2><p>项目和导入音频保存在此浏览器。点击提交生成后，确认的歌词和声音方向会经本机服务发给 ElevenLabs；任务和返回音频也保存在本机服务目录。清理浏览器数据会删除这些项目；换浏览器或换设备不会同步。重要成果请导出音频和歌词。</p><p>每个文件最大 30 MB、最长 5 分钟，每个版本最多 6 条音轨。导入音轨统一从 00:00 对齐，短轨补静音、长轨按作品时长截取。新导入的 WAV 按文件采样率解码；其他格式采用 48 kHz 编辑副本。新增导入完整保留原文件，编辑导出为 24 bit WAV。旧版已降采样的素材不会自动恢复音质。</p></section><section class="panel cap-card"><h2>怎样公平地比较</h2><p>A 是你指定的已保存基准版本，B 是当前修改。切换时保留播放位置，不做自动响度匹配；调整音量可能影响主观偏好，测试时请同时记录是否只是“更响”。</p><p>器乐示例的旋律、和声、贝斯与鼓是分别合成的独立音轨，并非从混合歌曲中自动拆分。用户歌词需要通过生成入口明确提交；修改草稿不会改变已有演唱。</p></section></div><h2 class="section-title">产品假设</h2><section class="panel cap-card"><p style="margin-top:0">有想法和歌词的音乐爱好者，能通过“说出意图 → 确认方案 → 试听比较 → 保留满意的变化”，逐步完成愿意分享的歌曲。当前工作台验证交互流程；完整歌曲生成质量与长期需求，需要结合真实用户和实际制作工具继续验证。</p><div class="flex" style="margin-top:20px"><button class="btn" data-act="page" data-page="research">查看验证记录</button><button class="btn quiet" data-act="request">准备制作需求单</button></div></section></main>`;}
return {shell,icon,waveHTML};
}
